from collections import Counter
class Solution:
    def mirrorFrequencyDistance(self, s):
        f = Counter(s)
        def mir(ch):
            if ch.isdigit():
                return str(9 - int(ch))
            return chr(ord('z') - (ord(ch) - ord('a')))
        ans = 0
        for c in f:
            m = mir(c)
            if c < m:
                ans += abs(f[c] - f.get(m, 0))
        return ans

