class Solution {
public:
    int mirrorFrequencyDistance(string s) {
        int f[128] = {0};
        for (char c : s) f[(unsigned char)c]++;
        long long ans = 0;
        for (int c = '0'; c <= 'z'; c++) {
            if (!f[c]) continue;
            int m = (c >= '0' && c <= '9') ? ('9' - (c - '0')) : ('z' - (c - 'a'));
            if (c < m) ans += abs(f[c] - f[m]);
        }
        return (int)ans;
    }
};

