class Solution {
    public int mirrorFrequencyDistance(String s) {
        int[] f = new int[128];
        for (char ch : s.toCharArray()) f[ch]++;
        int ans = 0;
        for (char c = '0'; c <= 'z'; c++) {
            if (f[c] == 0) continue;
            char m = (c >= '0' && c <= '9') ? (char)('9' - (c - '0')) : (char)('z' - (c - 'a'));
            if (c < m) ans += Math.abs(f[c] - f[m]);
        }
        return ans;
    }
}

