var mirrorFrequencyDistance = function(s) {
    const f = {};
    for (const ch of s) f[ch] = (f[ch] || 0) + 1;
    const mir = ch => (ch >= '0' && ch <= '9')
        ? String(9 - Number(ch))
        : String.fromCharCode(122 - (ch.charCodeAt(0) - 97));
    let ans = 0;
    for (const c in f) {
        const m = mir(c);
        if (c < m) ans += Math.abs(f[c] - (f[m] || 0));
    }
    return ans;
};
